import Foundation
import Testing
@testable import WristBridgeProtocol

// Reproduces test/fixtures/shared/p2-noise-xx-vectors.json (generated by the Kotlin implementation with fixed keys).
// NOT_RUN until executed on a Mac: `bash scripts/apple/test-package.sh`.

private struct NoiseVectors: Decodable {
    let prologueHex: String
    let initiatorStaticPrivateHex: String, responderStaticPrivateHex: String
    let initiatorEphemeralPrivateHex: String, responderEphemeralPrivateHex: String
    let message1Hex: String, message2Hex: String, message3Hex: String
    let handshakeHashHex: String, securityCode: String, transportAdHex: String
    let initiatorToResponderHex: String, responderToInitiatorHex: String
}

private func bytes(_ text: String) -> [UInt8] {
    var out: [UInt8] = []; var index = text.startIndex
    while index < text.endIndex {
        let next = text.index(index, offsetBy: 2)
        out.append(UInt8(text[index..<next], radix: 16)!)
        index = next
    }
    return out
}

private func hex(_ b: [UInt8]) -> String { b.map { String(format: "%02x", $0) }.joined() }

private func loadVectors() throws -> NoiseVectors {
    var url = URL(fileURLWithPath: #filePath)
    for _ in 0..<5 { url.deleteLastPathComponent() }
    return try JSONDecoder().decode(NoiseVectors.self,
        from: Data(contentsOf: url.appendingPathComponent("test/fixtures/shared/p2-noise-xx-vectors.json")))
}

@Suite struct P2NoiseTests {
    @Test func reproducesKotlinVectors() throws {
        let v = try loadVectors()
        let prologue = bytes(v.prologueHex)
        var initiator = P2NoiseXX(initiator: true, staticKey: try P2StaticKey(privateKey: bytes(v.initiatorStaticPrivateHex)),
                                  prologue: prologue, testEphemeral: try P2StaticKey(privateKey: bytes(v.initiatorEphemeralPrivateHex)))
        var responder = P2NoiseXX(initiator: false, staticKey: try P2StaticKey(privateKey: bytes(v.responderStaticPrivateHex)),
                                  prologue: prologue, testEphemeral: try P2StaticKey(privateKey: bytes(v.responderEphemeralPrivateHex)))
        let m1 = try initiator.writeMessage()
        #expect(hex(m1) == v.message1Hex)
        _ = try responder.readMessage(m1)
        let m2 = try responder.writeMessage(payload: Array("p2".utf8))
        #expect(hex(m2) == v.message2Hex)
        #expect(try initiator.readMessage(m2) == Array("p2".utf8))
        let m3 = try initiator.writeMessage(payload: Array("p3".utf8))
        #expect(hex(m3) == v.message3Hex)
        #expect(try responder.readMessage(m3) == Array("p3".utf8))
        var ti = try initiator.split()
        var tr = try responder.split()
        #expect(hex(ti.handshakeHash) == v.handshakeHashHex)
        #expect(ti.securityCode == v.securityCode && tr.securityCode == v.securityCode)
        let ad = bytes(v.transportAdHex)
        let c1 = try ti.send.seal(ad: ad, Array("initiator-to-responder".utf8))
        let c2 = try tr.send.seal(ad: ad, Array("responder-to-initiator".utf8))
        #expect(hex(c1) == v.initiatorToResponderHex)
        #expect(hex(c2) == v.responderToInitiatorHex)
        #expect(try tr.receive.open(ad: ad, c1) == Array("initiator-to-responder".utf8))
        #expect(try ti.receive.open(ad: ad, c2) == Array("responder-to-initiator".utf8))
    }

    @Test func tamperedAndReplayedMessagesAreRejected() throws {
        var a = P2NoiseXX(initiator: true, staticKey: .generate(), prologue: [1])
        var b = P2NoiseXX(initiator: false, staticKey: .generate(), prologue: [1])
        _ = try b.readMessage(try a.writeMessage())
        _ = try a.readMessage(try b.writeMessage())
        _ = try b.readMessage(try a.writeMessage())
        var ta = try a.split(), tb = try b.split()
        let ct = try ta.send.seal(ad: [], Array("uno".utf8))
        var bad = ct; bad[0] ^= 1
        #expect(throws: P2Error.badTag) { _ = try tb.receive.open(ad: [], bad) }
        #expect(try tb.receive.open(ad: [], ct) == Array("uno".utf8))
        #expect(throws: P2Error.badTag) { _ = try tb.receive.open(ad: [], ct) }
    }
}
